  k1[2] = qop*(B1[1]*dir[0] - x4);
  k1[3] = x7;
  k1[4] = x10*x8;
  const auto x14 = pos[0] + (1.0/2.0)*x11 + x13*k1[0];
  const auto x16 = pos[1] + x13*k1[1] + (1.0/2.0)*x15;
  const auto x18 = pos[2] + x13*k1[2] + (1.0/2.0)*x17;
  std::array<T, 3> pos2{};
  pos2[0] = x14;
  pos2[1] = x16;
  pos2[2] = x18;
  const auto B2res = getB(std::span<const T, 3>(pos2));
    if (!B2res.ok()) {
      fieldErr = B2res.error();
      return Acts::detail::Rk4Status::FieldError;
    }
    const auto B2 = *B2res;
  const auto x26 = h*k1[4];
  const auto x27 = qop + (1.0/2.0)*x26;
  T qop2{};
  qop2 = x27;
  const auto dEds2 = getG(std::span<const T, 3>(pos2), qop2);
  const auto x21 = (1.0/2.0)*h;
  const auto x39 = std::pow(x27, 2);
  const auto x38 = dEds2*x5;
  const auto x22 = dir[0] + x21*k1[0];
  const auto x23 = dir[1] + x21*k1[1];
  const auto x24 = dir[2] + x21*k1[2];
  const auto x25 = dtds + x21*k1[3];
  const auto x34 = B2[1]*x24;
  const auto x35 = B2[0]*x24;
  const auto x36 = B2[2]*x22;
  const auto x37 = B2[0]*x23;
  const auto x40 = dEds2*x25*x9;
  std::array<T, 5> k2{};
  k2[0] = x27*(B2[2]*x23 - x34);
  k2[1] = x27*(x35 - x36);
  k2[2] = x27*(B2[1]*x22 - x37);
  k2[3] = std::pow(x27, 3)*x38;
  k2[4] = x39*x40;
  const auto x32 = h*k2[4];
  const auto x33 = qop + (1.0/2.0)*x32;
  T qop3{};
  qop3 = x33;
  const auto dEds3 = getG(std::span<const T, 3>(pos2), qop3);
  const auto x46 = std::pow(x33, 2);
  const auto x48 = (1.0/2.0)*x12;
  const auto x45 = dEds3*x5;
  const auto x49 = pos[0] + x11;
  const auto x51 = pos[1] + x15;
  const auto x53 = pos[2] + x17;
  const auto x28 = dir[0] + x21*k2[0];
  const auto x29 = dir[1] + x21*k2[1];
  const auto x30 = dir[2] + x21*k2[2];
  const auto x31 = dtds + x21*k2[3];
  const auto x41 = B2[1]*x30;
  const auto x42 = B2[0]*x30;
  const auto x43 = B2[2]*x28;
  const auto x44 = B2[0]*x29;
  const auto x47 = dEds3*x31*x9;
  std::array<T, 5> k3{};
  k3[0] = x33*(B2[2]*x29 - x41);
  k3[1] = x33*(x42 - x43);
  k3[2] = x33*(B2[1]*x28 - x44);
  k3[3] = std::pow(x33, 3)*x45;
  k3[4] = x46*x47;
  const auto x50 = x49 + x48*k3[0];
  const auto x52 = x51 + x48*k3[1];
  const auto x54 = x53 + x48*k3[2];
  std::array<T, 3> pos3{};
  pos3[0] = x50;
  pos3[1] = x52;
  pos3[2] = x54;
  const auto B3res = getB(std::span<const T, 3>(pos3));
    if (!B3res.ok()) {
      fieldErr = B3res.error();
      return Acts::detail::Rk4Status::FieldError;
    }
    const auto B3 = *B3res;
  const auto x61 = h*k3[4];
  const auto x62 = qop + x61;
  T qop4{};
  qop4 = x62;
  const auto dEds4 = getG(std::span<const T, 3>(pos3), qop4);
  const auto x68 = std::pow(x62, 2);
  const auto x67 = dEds4*x5;
  const auto x57 = dir[0] + h*k3[0];
  const auto x58 = dir[1] + h*k3[1];
  const auto x59 = dir[2] + h*k3[2];
  const auto x60 = dtds + h*k3[3];
  const auto x63 = B3[1]*x59;
  const auto x64 = B3[0]*x59;
  const auto x65 = B3[2]*x57;
  const auto x66 = B3[0]*x58;
  const auto x69 = dEds4*x68*x9;
  std::array<T, 5> k4{};
  k4[0] = x62*(B3[2]*x58 - x63);
  k4[1] = x62*(x64 - x65);
  k4[2] = x62*(B3[1]*x57 - x66);
  k4[3] = std::pow(x62, 3)*x67;
  k4[4] = x60*x69;
  const auto x70 = k1[0] + k4[0];
  const auto x71 = k1[1] + k4[1];
  const auto x72 = k1[2] + k4[2];
  err = x12*(std::fabs(k2[0] + k3[0] - x70) + std::fabs(k2[1] + k3[1] - x71) + std::fabs(k2[2] + k3[2] - x72));
  if (err > errTol) {
    return Acts::detail::Rk4Status::Rejected;
  }
  new_B[0] = B3[0];
  new_B[1] = B3[1];
  new_B[2] = B3[2];
  const auto x73 = (1.0/6.0)*x12;
  const auto x74 = x49 + x73*(k1[0] + k2[0] + k3[0]);
