  new_pos[1] = x75;
  new_pos[2] = x76;
  const auto x19 = dtds*h;
  const auto x55 = time + x19;
  const auto x77 = x55 + x73*(k1[3] + k2[3] + k3[3]);
  new_time = x77;
  const auto x78 = (1.0/6.0)*h;
  const auto x79 = dir[0] + x78*(x70 + 2*k2[0] + 2*k3[0]);
