  const auto x83 = 1.0/std::sqrt(std::pow(std::fabs(new_dir_unnorm[0]), 2) + std::pow(std::fabs(new_dir_unnorm[1]), 2) + std::pow(std::fabs(new_dir_unnorm[2]), 2));
  new_dir[0] = x83*new_dir_unnorm[0];
